class IndependentSpyAaplStrategies(QCAlgorithm):
    """Two independent, close-of-day strategies with separately tracked lots."""

    SMA_PERIOD = 20
    RSI_PERIOD = 14

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma = self.SMA(
            self.symbols["SPY"], self.SMA_PERIOD, Resolution.Daily
        )
        self.aapl_rsi = self.RSI(
            self.symbols["AAPL"],
            self.RSI_PERIOD,
            MovingAverageType.Wilders,
            Resolution.Daily,
        )

        self.previous_closes = {}
        self.previous_spy_above_sma = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data: Slice):
        bars = data.Bars

        # Market state advances whenever its ticker has a bar, even when another
        # ticker is missing and trading rules must therefore be skipped.
        aapl = self.symbols["AAPL"]
        if aapl in bars:
            aapl_close = bars[aapl].Close
            previous_aapl_close = self.previous_closes.get(aapl)
            if previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.previous_closes[aapl] = aapl_close

        spy = self.symbols["SPY"]
        current_spy_above_sma = None
        if spy in bars and self.spy_sma.IsReady:
            current_spy_above_sma = bars[spy].Close > self.spy_sma.Current.Value

        complete_slice = all(symbol in bars for symbol in self.symbols.values())
        all_state_ready = (
            self.spy_sma.IsReady
            and self.aapl_rsi.IsReady
            and self.previous_spy_above_sma is not None
            and aapl in self.previous_closes
        )

        if complete_slice and all_state_ready:
            spy_crossed_above = (
                not self.previous_spy_above_sma and current_spy_above_sma
            )
            spy_crossed_below = (
                self.previous_spy_above_sma and not current_spy_above_sma
            )

            # Sells are evaluated before buys.
            if self.spy_lot > 0 and spy_crossed_below:
                self.MarketOrder(spy, -self.spy_lot, tag="Strategy A sell")
                self.spy_lot = 0

            if self.aapl_lot > 0 and self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(aapl, -self.aapl_lot, tag="Strategy B sell")
                self.aapl_lot = 0

            if self.spy_lot == 0 and spy_crossed_above:
                quantity = floor(
                    0.40 * self.Portfolio.TotalPortfolioValue / bars[spy].Close
                )
                if quantity > 0:
                    self.MarketOrder(spy, quantity, tag="Strategy A buy")
                    self.spy_lot = quantity

            if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
                cash_to_invest = 20_000
                if self.Portfolio.Cash >= cash_to_invest:
                    quantity = floor(cash_to_invest / bars[aapl].Close)
                    if quantity > 0:
                        self.MarketOrder(aapl, quantity, tag="Strategy B buy")
                        self.aapl_lot = quantity

        if current_spy_above_sma is not None:
            self.previous_spy_above_sma = current_spy_above_sma

